<script module lang="ts">
/**
 * Toast.Viewport: the one viewport the application mounts, which draws every toast the store holds.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  TOAST_QUIET,
  actOnToastNotice,
  agentMember,
  announceToasts,
  dismissToastNotice,
  followToastFocus,
  getToasts,
  holdToastTimers,
  joinSlot,
  subscribeToasts,
  toast,
  toastDetails,
  toastNotices,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/overlays/toast.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import ToastCard from './ToastCard.svelte'
import type { ToasterMessages } from './Toast.svelte'

export interface ToastViewportProps {
  /**
   * The close button’s name, the announcement’s prefix and the region’s name, from the catalog.
   */
  messages?: ToasterMessages
}
</script>

<script lang="ts">
let { messages }: ToastViewportProps = $props()
const joined = joinSlot(undefined, () => ({}))
let version = $state(0)
let paused = $state(false)
let said = $state(TOAST_QUIET)
let list = $state<HTMLElement | null>(null)
let region = $state<HTMLElement | null>(null)
const say = $derived(
  messages ?? { dismiss: 'Dismiss', notification: 'Notification', viewport: 'Notifications (F8)' },
)
const records = $derived(version < 0 ? [] : getToasts())
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran =
    ((version += 1),
    subscribeToasts(() => {
      version += 1
    }))
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const listener = (event: DocumentEventMap['keydown']) => {
    event.key === 'F8' && (event.preventDefault(), list?.focus())
  }
  document.addEventListener('keydown', listener)
  release2 = () => document.removeEventListener('keydown', listener)
}
watchEffect(effect2)
onDestroy(() => release2?.())
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = holdToastTimers(region, (held) => {
    paused = held
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = followToastFocus(list)
  release4 = () => {
    ran()
  }
}
watchEffect(effect4)
onDestroy(() => release4?.())
const effect5 = () => {
  said = announceToasts(said, records, list, say.notification)
}
watchEffect(effect5, { watch: () => version })
let release6: (() => void) | undefined
const effect6 = () => {
  release6?.()
  const ran = agentMember({
    member: 'Toast',
    element: () => region,
    state: () => ({ notices: toastNotices(getToasts()), details: toastDetails(getToasts()) }),
    actions: {
      dismiss: { argument: 'id', run: (value) => dismissToastNotice(toast, getToasts(), value) },
      act: { argument: 'id', run: (value) => actOnToastNotice(toast, getToasts(), value) },
    },
    withholds: () => [...(list?.querySelectorAll('[data-member="toast"] > div ~ div') ?? [])],
  })
  release6 = () => {
    ran()
  }
}
watchEffect(effect6)
onDestroy(() => release6?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div bind:this={region} role="region" aria-label={say.viewport} tabindex="-1"
    ><ol bind:this={list} class={styles.viewport} tabindex="-1" data-toast-part="list"
      >{#each records as record (record.id)
        }<ToastCard {record} dismissLabel={say.dismiss} {paused}
      />{/each
    }</ol
    ><div class={a11y.visuallyHidden} role="status" aria-live="polite" aria-atomic="true"
      >{#each [said.polite] as saying (saying.key)}<span>{saying.words}</span>{/each
    }</div
    ><div class={a11y.visuallyHidden} role="alert" aria-live="assertive" aria-atomic="true"
      >{#each [said.assertive] as saying (saying.key)}<span>{saying.words}</span>{/each
    }</div
  ></div
>{/if
}{@render joined.end?.()}
